<parameter name="content">import { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;

    if (error) {
      return (
        this.props.fallback ?? (
          <div role="alert" style={styles.container}>
            <h2 style={styles.title}>Something went wrong</h2>
            <pre style={styles.message}>{error.message}</pre>
            <button onClick={this.retry} style={styles.button}>
              Try again
            </button>
          </div>
        )
      );
    }

    return this.props.children;
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    gap: "1rem",
    fontFamily: "sans-serif",
  },
  title: { margin: 0, fontSize: "1.25rem", color: "#b91c1c" },
  message: {
    background: "#fef2f2",
    border: "1px solid #fecaca",
    borderRadius: "6px",
    padding: "0.75rem 1rem",
    fontSize: "0.875rem",
    maxWidth: "480px",
    overflowX: "auto",
  },
  button: {
    padding: "0.5rem 1.25rem",
    borderRadius: "6px",
    border: "none",
    background: "#2563eb",
    color: "#fff",
    fontSize: "0.9rem",
    cursor: "pointer",
  },
};
