<parameter name="content">import { render, screen, fireEvent } from "@testing-library/react";
import { ErrorBoundary } from "./ErrorBoundary";

const Throw = ({ shouldThrow }: { shouldThrow: boolean }) => {
  if (shouldThrow) throw new Error("boom");
  return <div>ok</div>;
};

beforeEach(() => jest.spyOn(console, "error").mockImplementation(() => {}));
afterEach(() => jest.restoreAllMocks());

test("renders children when there is no error", () => {
  render(
    <ErrorBoundary>
      <Throw shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("ok")).toBeInTheDocument();
});

test("shows fallback UI and logs on render error", () => {
  render(
    <ErrorBoundary>
      <Throw shouldThrow={true} />
    </ErrorBoundary>
  );
  expect(screen.getByRole("alert")).toBeInTheDocument();
  expect(screen.getByText("boom")).toBeInTheDocument();
  expect(console.error).toHaveBeenCalledWith(
    "[ErrorBoundary]",
    "boom",
    expect.objectContaining({ stack: expect.any(String) })
  );
});

test("retry button resets the error state", () => {
  const { rerender } = render(
    <ErrorBoundary>
      <Throw shouldThrow={true} />
    </ErrorBoundary>
  );
  fireEvent.click(screen.getByRole("button", { name: /try again/i }));
  rerender(
    <ErrorBoundary>
      <Throw shouldThrow={false} />
    </ErrorBoundary>
  );
  expect(screen.getByText("ok")).toBeInTheDocument();
});

test("renders custom fallback when provided", () => {
  render(
    <ErrorBoundary fallback={<p>custom fallback</p>}>
      <Throw shouldThrow={true} />
    </ErrorBoundary>
  );
  expect(screen.getByText("custom fallback")).toBeInTheDocument();
});
